import{SelectFilterInput,AssignedEntityFilterInput,DateFilterInput,TextFilterInput}from"/js/dist/filterInputs.min.js";import{container}from"/js/dist/simpleDIContainer.min.js";export default class FilterFormManager{constructor(){this.filters=[],this.inputs=[],this.apiService=container.resolve("apiService")}async collectFilterInputs(){this.inputs=[];const e=[];return document.querySelectorAll('select[id^="advancedSearch_"]:not(.no-select2)').forEach((t=>{e.push(new Promise((e=>{setTimeout((()=>{this.inputs.push(new SelectFilterInput(t,this.apiService)),e()}),0)})))})),document.querySelectorAll(".input-daterange.input-group.date-range-input").forEach((e=>{this.inputs.push(new DateFilterInput(e,this.apiService))})),document.querySelectorAll('input[id^="advancedSearch_"][type="text"]').forEach((t=>{e.push(new Promise((e=>{queueMicrotask((()=>t.classList.contains("input-daterange-field")?e():t.classList.contains("advancedSearch_polymorphicItemFormatter")?(this.inputs.push(new AssignedEntityFilterInput(t,this.apiService)),e()):(this.inputs.push(new TextFilterInput(t,this.apiService)),void e())))})))})),await Promise.all(e),this.inputs}collectFilterData(){return this.filters=[],this.inputs.forEach((e=>{e.appendTo(this.filters)})),this.filters}clearAll(){this.inputs.forEach((e=>{e.clear()}))}setValuesFromResponse(e){this.clearAll();const t=[];for(const i of e){const{field:e,value:s,logic:n,operator:r}=i,a=this.inputs.find((t=>t.key===e));if(a)try{const e=a.setValue(s,n,r);e instanceof Promise&&t.push(e)}catch(t){console.error(`Failed to set value for "${e}":`,t)}else console.warn(`No input found for key: ${e}`)}return Promise.all(t).then((e=>(this.setAdvancedSearchPanelFilterEnabledState(!1),e)))}setAdvancedSearchPanelFilterEnabledState(e){queueMicrotask((()=>{const t=document.getElementById("advancedSearchPanel").getElementsByTagName("*");for(const i of t)i.disabled=e}))}}
